-- ============================================================
--  042_guide_shorter_rollback.sql
--  คืนข้อความคู่มือกลับเป็นฉบับก่อนย่อ
--
--  ไฟล์นี้ถูกสร้างจากค่าจริงในฐานข้อมูลก่อนรัน 042 ไม่ได้เขียนมือ
--  จึงคืนได้ตรงทุกตัวอักษร ครอบคลุมเฉพาะขั้นที่ 042 แตะ (73 ขั้น)
--
--  หมายเหตุ: 042 ทับข้อความปุ่มกล้องที่ 041 แก้ไว้ด้วย การย้อนไฟล์นี้
--  จะได้ข้อความฉบับ 041 กลับมา (ซึ่งบอกว่ากล้องอ่านบาร์โค้ดได้)
--
--  วิธีรัน:
--      mysql -u root -p1234 stock_hr < sql/042_guide_shorter_rollback.sql
-- ============================================================

SET NAMES utf8;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'หน่วยงานทุกหน่วยต้องสังกัดบริษัทใดบริษัทหนึ่ง เพราะโลโก้และรหัสแบบฟอร์มบนใบเบิกที่พิมพ์ออกมาถูกเลือกจากบริษัทของหน่วยงานนั้น หลายบริษัทมีหน่วยงานชื่อซ้ำกัน เช่นจัดซื้อหรือบัญชี ซึ่งเป็นคนละหน่วยงานกัน'
WHERE g.`page_key` = 'agencies' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'บัญชีที่ผู้ดูแลเพิ่งสร้างให้จะมีรหัสตั้งต้นเหมือนกันทุกคน ควรเปลี่ยนทันทีที่เข้าระบบครั้งแรก เปลี่ยนเสร็จแล้วระบบจะให้เข้าสู่ระบบใหม่ด้วยรหัสใหม่'
WHERE g.`page_key` = 'change_password' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ตัวเลขใหญ่คือจำนวนเอกสารที่รอ \"คุณ\" ทำอะไรสักอย่าง ไม่ใช่จำนวนงานทั้งระบบ ถ้าเป็นศูนย์แปลว่าไม่มีอะไรค้างอยู่ที่คุณ บรรทัดใต้ตัวเลขแยกให้ว่าเป็นงานประเภทไหนบ้าง เช่นรออนุมัติกี่ใบ รอเซ็นรับของกี่ใบ ส่วนตัวเลขแถบล่างสุดของไทล์เป็นภาพรวมที่ควรรู้ไว้ แต่ยังไม่ใช่งานที่ต้องทำวันนี้'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'กล่องนี้บอกว่างานที่ค้างอยู่คือใบไหนบ้าง ต่างจากไทล์เขียวข้าง ๆ ที่บอกแค่จำนวน กดที่บรรทัดไหนก็ได้เพื่อกระโดดไปที่เอกสารใบนั้นทันที ไม่ต้องไปไล่หาในหน้าประวัติเอง แสดงได้สูงสุดห้าใบเรียงตามความเร่งด่วน คืองานที่มีคนอื่นรออยู่มาก่อน ถ้ามีมากกว่านั้นให้กดดูใบเบิกทั้งหมดที่มุมขวาบนของกล่อง'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'หัวข้อที่มีลูกศรกดแล้วกางเมนูย่อยออกมา รายการที่คุณเห็นไม่เท่ากับของคนอื่น เพราะขึ้นกับสิทธิ์ที่ผู้ดูแลระบบตั้งไว้ ถ้าหาเมนูที่เพื่อนบอกไม่เจอ แปลว่าสิทธิ์ของคุณยังไม่เปิดหน้านั้น ไม่ใช่ระบบเสีย · ปุ่มลูกศรที่หัวเมนูใช้ย่อให้เหลือแต่ไอคอน เอาไว้ตอนอยากได้พื้นที่อ่านตารางกว้าง ๆ ระบบจำสถานะที่ย่อไว้ให้ในเครื่องนี้'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'กดจากตรงนี้ได้เลยโดยไม่ต้องไปหาในเมนูซ้าย รายการที่ขึ้นเปลี่ยนตามสิทธิ์ของคุณ จึงมีเฉพาะหน้าที่คุณเข้าได้จริง ไม่มีลิงก์ที่กดแล้วเจอ \"ไม่มีสิทธิ์เข้าถึง\"'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ไทล์นี้โผล่เฉพาะตอนที่ทะเบียนสินค้ายังกรอกไม่ครบ และหายไปเองเมื่อกรอกครบแล้ว มีไว้เพราะค่าที่ขาดไปไม่ได้ทำให้ระบบพัง แต่ทำให้ตัวเลขในไทล์อื่นเงียบ ๆ ผิดไปจากความจริง สินค้าที่ไม่ได้ตั้งราคาจะถูกคิดเป็นศูนย์ในทุกยอดเงิน ส่วนสินค้าที่ไม่ได้ตั้งจุดสั่งซื้อจะไม่มีวันขึ้นเตือนว่าใกล้หมด แม้ของจะหมดจริงก็ตาม แต่ละบรรทัดบอกทั้งจำนวนที่ยังขาดและผลที่ตามมา พร้อมปุ่มไปยังหน้าที่ใช้แก้ ไม่ต้องแก้ทีเดียวหมดก็ได้ เปอร์เซ็นต์ด้านบนจะขยับขึ้นทุกครั้งที่กรอกเพิ่ม'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 5;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'แท่งเขียวคือของเข้า แท่งส้มคือของออก ชี้ค้างที่แท่งไหนก็ได้เพื่อดูตัวเลขของช่วงนั้น ถ้าเลือกช่วงยาวจนแท่งเบียดกัน กราฟจะเปลี่ยนเป็นเส้นให้เองเพื่อให้ยังอ่านแนวโน้มได้'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 6;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'สี่ปุ่มนี้ครอบช่วงที่ถามกันบ่อยที่สุด กดแล้วจะตั้งความละเอียดที่เหมาะกับช่วงนั้นให้ด้วย เช่น \"3 ปี\" จะดูเป็นรายปี เพราะสามปีที่ดูรายวันคือกว่าพันแท่งซึ่งอ่านไม่ออก'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 7;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เปลี่ยนความละเอียดแยกจากช่วงได้ เช่นดูทั้งปีแบบรายวันเพื่อหาว่าของออกหนักวันไหน หรือดูสามปีแบบรายเดือนเพื่อดูฤดูกาล ถ้าช่วงยาวเกินจนเกิน 400 ช่วง ระบบจะตัดให้แล้วบอกไว้ใต้กราฟ'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 8;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'สองตัวเลขนี้คนละเรื่องกัน — \"ซื้อเข้า\" คือเงินที่จ่ายไปกับของที่รับเข้าคลังเดือนนี้ ส่วน \"เบิกไปใช้\" คือมูลค่าของที่หน่วยงานเบิกออกไปใช้ ไม่จำเป็นต้องเท่ากัน เพราะของที่ซื้อเดือนนี้อาจถูกเบิกเดือนหน้า ทั้งคู่คิดจากราคาที่ตั้งไว้ในทะเบียนสินค้า ถ้ามีบรรทัดหมายเหตุอยู่ท้ายไทล์ ให้อ่านด้วยเสมอ เพราะมันบอกว่ายอดพวกนี้คิดจากสินค้ากี่รายการจากทั้งหมด สินค้าที่ยังไม่ได้ตั้งราคาถูกนับเป็นศูนย์ ยอดจริงจึงสูงกว่าที่เห็น กดที่ไทล์เพื่อไปดูรายละเอียดแยกตามบริษัทและหน่วยงานได้'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 9;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'รายการที่ยอดคงเหลือถึงหรือต่ำกว่าจุดสั่งซื้อที่ตั้งไว้ในทะเบียนสินค้า สิ่งที่ต้องดูคู่กันเสมอคือบรรทัดเล็กใต้ตัวเลข ซึ่งบอกว่าตัวเลขนี้นับมาจากฐานกว้างแค่ไหน ถ้าขึ้นว่า \"นับจากที่ตั้งจุดสั่งซื้อแล้ว 1/313 รายการ\" แปลว่าเลขที่เห็นครอบคลุมสินค้าแค่รายการเดียว อีก 312 รายการต่อให้ของหมดก็ไม่ถูกนับ กรณีแบบนี้เลข 0 ไม่ได้แปลว่าของครบ แต่แปลว่ายังไม่ได้ตั้งค่า ไทล์จะเป็นสีส้มเตือนไว้ให้ด้วย'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 10;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'หกรายการหลังสุดที่ทำให้ยอดคงเหลือเปลี่ยน ไม่ใช่ทั้งหมดของวันนี้ ใช้กวาดตาดูว่ามีอะไรผิดปกติไหมตอนเปิดระบบตอนเช้า ถ้าต้องไล่ย้อนหลังจริงจังให้ไปที่รายงานความเคลื่อนไหว ซึ่งค้นและกรองตามช่วงวันที่ได้'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 11;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ตัวเลขแดงคือเรื่องที่ยังไม่ได้อ่าน กดแล้วจะเห็นรายการจัดกลุ่มตามวัน เลื่อนลงถึงท้ายจะโหลดเพิ่มให้เอง ท้ายกล่องมีสวิตช์ \"แจ้งเตือนนอกหน้าเว็บ\" ที่ทำให้เรื่องใหม่เด้งเป็นกล่องมุมจอแม้คุณสลับไปทำอย่างอื่น'
WHERE g.`page_key` = 'dashboard' AND s.`step_order` = 12;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'สถานะ \"จ่ายแล้ว\" คือของออกจากคลังไปแล้วแต่ผู้เบิกยังไม่ได้เซ็นรับ ส่วน \"รับของแล้ว\" คือปิดเรื่องเรียบร้อย ใบที่ค้างสถานะแรกนาน ๆ คือใบที่ต้องตามเรื่อง (แถวบนสุดตอนนี้เป็นตัวอย่างสำหรับสาธิต จะหายไปเองตอนปิดคู่มือ)'
WHERE g.`page_key` = 'issue_history' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'คัดลอกลิงก์สำหรับให้ผู้เบิกเซ็นรับ เปิดได้โดยไม่ต้องล็อกอิน ส่งทางไลน์ได้เลยตอนที่เขาหาอีเมลไม่เจอ ลิงก์ใช้ได้ 7 วันและใครถือก็เซ็นรับแทนได้ จึงส่งให้เฉพาะผู้เบิกเท่านั้น กดส่งเมลซ้ำเมื่อไร ลิงก์เดิมจะถูกยกเลิกทันที'
WHERE g.`page_key` = 'issue_history' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เปิดผืนให้เซ็นด้วยนิ้วหรือเมาส์ ลายเซ็นจะถูกเก็บไว้กับเอกสารและพิมพ์ติดไปบนกระดาษ ผู้ดูแลระบบเซ็นแทนได้เมื่อผู้เบิกมารับที่คลังโดยตรง เซ็นแล้วใบจะปิดและแก้ไม่ได้อีก'
WHERE g.`page_key` = 'issue_history' AND s.`step_order` = 6;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'หน้านี้เริ่มจากใบเบิกที่อนุมัติแล้วและยังจ่ายไม่ครบเท่านั้น เลือกเองไม่ได้ว่าจะจ่ายอะไร ถ้าไม่มีตัวเลือกขึ้นมาเลย แปลว่าไม่มีใบเบิกที่รอจ่ายอยู่ ต้องให้ผู้อนุมัติตัดสินใบที่ค้างก่อน (ระหว่างเปิดคู่มือนี้ ระบบใส่ใบเบิกตัวอย่างไว้ให้ดู จะหายไปเองตอนปิด)'
WHERE g.`page_key` = 'issue_new' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'หน้านี้เพิ่มบรรทัดเองไม่ได้ รายการทั้งหมดมาจากใบเบิกที่เลือกไว้ การยิงตรงนี้จึงไม่ใช่การเพิ่มสินค้า แต่เป็นการนับของที่หยิบใส่กล่องไปแล้ว หยิบของหนึ่งชิ้นก็ยิงหนึ่งครั้ง ระบบจะบวกจำนวนในบรรทัดของสินค้านั้นให้ทีละหนึ่ง แล้วขึ้นข้อความบอกความคืบหน้า เช่น \"หยิบแล้ว 2 จาก 5 ม้วน\" หมายถึงหยิบไปแล้ว 2 ม้วน จากที่ใบเบิกขอมา 5 ม้วน เมื่อหยิบครบตามจำนวนที่ขอ ระบบจะเตือนว่าไม่ต้องหยิบเพิ่มแล้ว ประโยชน์ที่สำคัญที่สุดคือการจับว่าหยิบผิดตัว ถ้ายิงสินค้าที่ไม่มีอยู่ในใบเบิกใบนี้ ระบบจะเตือนพร้อมเสียงต่ำทันที ตอนที่ของยังอยู่ในมือ ไม่ใช่ตอนที่ส่งไปถึงหน่วยงานแล้ว ช่องนี้รับได้ทั้งฉลากแบบบาร์โค้ดและแบบ QR โดยไม่ต้องสลับโหมด'
WHERE g.`page_key` = 'issue_new' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'กดปุ่มนี้เพื่อเปิดกล้องของเครื่องแล้วส่อง QR ที่ฉลากแทนการยิง เหมาะกับตอนเดินหยิบของอยู่ในคลังแล้วถือมือถือไปด้วย ไม่ต้องกดถ่าย เล็งให้ QR อยู่ในกรอบแล้วระบบอ่านเอง ส่องติดแล้วจะนับจำนวนที่หยิบให้เหมือนการยิงทุกอย่าง แล้วปิดกล้องให้เองหลังจากโชว์ผลให้อ่านครู่หนึ่ง แต่ถ้าส่องแล้วเจอของที่ไม่มีในใบเบิก หรือหยิบครบตามจำนวนที่ขอแล้ว กล้องจะเปิดค้างไว้พร้อมข้อความเตือน เพราะเป็นจังหวะที่ต้องเล็งตัวใหม่ต่อทันที ข้อจำกัดสองข้อ: กล้องอ่านได้เฉพาะ QR ไม่ใช่บาร์โค้ด และเบราว์เซอร์จะไม่ยอมเปิดกล้องถ้าระบบยังเข้าผ่าน http ธรรมดา'
WHERE g.`page_key` = 'issue_new' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ระบบเติมจำนวนที่ยังค้างจ่ายให้ล่วงหน้า แก้ให้น้อยลงได้ถ้าของมีไม่พอ ส่วนที่เหลือจะยังค้างอยู่ที่ใบเบิกเดิม ทำใบจ่ายรอบสองทีหลังได้ ใบเบิกจะปิดก็ต่อเมื่อจ่ายครบทุกบรรทัด กรอกเกินจำนวนที่ขอไว้หรือเกินยอดคงเหลือไม่ได้ ระบบจะเตือนตั้งแต่ตอนพิมพ์'
WHERE g.`page_key` = 'issue_new' AND s.`step_order` = 5;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'กดแล้วยอดคงเหลือลดทันที และระบบส่งอีเมลพร้อมลิงก์ให้ผู้ขอเบิกมาเซ็นรับ ลิงก์นั้นเปิดได้เลยไม่ต้องล็อกอิน บันทึกผิดต้องยกเลิกทั้งใบที่หน้าประวัติการจ่ายออก ซึ่งจะคืนของกลับเข้าสต๊อกและคืนยอดค้างให้ใบเบิกต้นทาง'
WHERE g.`page_key` = 'issue_new' AND s.`step_order` = 7;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'รวมทุกเรื่องที่เคยแจ้งคุณ เรียงใหม่สุดอยู่บน จัดกลุ่มตามวันให้แล้ว โหลดมาทีละ 10 เรื่อง เลื่อนลงถึงท้ายจะโหลดต่อเอง ที่นี่เห็นเฉพาะของคุณ แม้แต่ผู้ดูแลระบบสูงสุดก็ดูของคนอื่นทางนี้ไม่ได้'
WHERE g.`page_key` = 'notifications' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เปิดสวิตช์แล้วเรื่องใหม่จะเด้งเป็นกล่องมุมจอ แม้คุณสลับไปทำอย่างอื่น แต่ต้องเปิดหน้าระบบค้างไว้ในแท็บใดแท็บหนึ่ง ปิดเบราว์เซอร์ไปเลยจะไม่มีอะไรเด้ง ถ้าสวิตช์กดไม่ลง ให้อ่านเหตุผลข้าง ๆ — ส่วนใหญ่เพราะเบราว์เซอร์อนุญาตเฉพาะเว็บที่เข้าผ่าน https'
WHERE g.`page_key` = 'notifications' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เมนูถูกจัดกลุ่มตามหัวข้อบนแถบซ้าย กดที่หัวกลุ่มเพื่อกางหรือพับ กลุ่มที่มีเมนูเดียวจะไม่มีหัวกลุ่ม เพราะพับแล้วไม่ได้อะไร ติ๊กในช่องเพื่อเปิดสิทธิ์ ติ๊กออกเพื่อปิด'
WHERE g.`page_key` = 'permissions' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ไม่ใช่แค่ซ่อนเมนู คนที่ไม่มีสิทธิ์พิมพ์ที่อยู่หน้านั้นตรง ๆ ก็จะเจอหน้าไม่มีสิทธิ์เข้าถึง ส่วนผู้ดูแลระบบสูงสุดเข้าได้ทุกเมนูเสมอ ปรับไม่ได้ เพื่อไม่ให้เผลอปิดสิทธิ์ตัวเองจนไม่มีใครแก้คืนได้'
WHERE g.`page_key` = 'permissions' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'หน้านี้แปลงรหัสสินค้าที่มีอยู่แล้วให้เป็นบาร์โค้ดที่เครื่องอ่านยิงได้ ไม่ได้สร้างรหัสใหม่และไม่ได้บันทึกอะไรลงระบบเลย จึงเปิดมาลองกดเล่นได้โดยไม่ต้องกลัวข้อมูลเสีย ค้นหาด้วยรหัสสินค้า ชื่อสินค้า หรือรหัสเดิมก็ได้ แล้วติ๊กเลือกรายการที่ต้องการ เลือกได้หลายรายการพร้อมกัน'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ปุ่มนี้เลือกทุกรายการที่แสดงอยู่ตอนนั้น ไม่ใช่ทุกรายการในระบบ จึงใช้คู่กับช่องค้นหาได้ เช่น พิมพ์ CS-MED เพื่อกรองเฉพาะกลุ่มยา แล้วกดปุ่มนี้เพื่อเลือกทั้งกลุ่มในครั้งเดียว เหมาะกับตอนตั้งชั้นวางใหม่ที่ต้องทำฉลากทีละหมวด'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ทั้งสองแบบเก็บรหัสสินค้าตัวเดียวกันเป๊ะ ต่างกันแค่ใครอ่านได้ บาร์โค้ดใช้กับเครื่องยิงที่เสียบกับคอมพิวเตอร์ ซึ่งเป็นวิธีที่เร็วที่สุดตอนรับเข้าหรือจ่ายของทีละหลายรายการ ส่วน QR ส่องด้วยกล้องมือถือธรรมดาได้ เหมาะกับคนที่ไม่มีเครื่องยิงติดตัว เช่นตอนไปนับของที่ชั้นวางหรือหน้างานนอกห้องคลัง ข้อควรรู้: เครื่องยิงเลเซอร์แบบเส้นตรงส่วนใหญ่อ่าน QR ไม่ได้ ต้องเป็นรุ่นที่เป็นกล้อง (2D imager) เท่านั้น ถ้าไม่แน่ใจว่าเครื่องที่มีอยู่เป็นแบบไหน ให้ลองยิงดูจากตัวอย่างบนหน้าจอนี้ได้เลย เมื่อเลือก QR จะมีตัวเลือกการจัดวางโผล่ขึ้นมาใต้ปุ่มนี้ ให้เลือกได้ว่าจะเอา QR ไว้ทางซ้ายแล้ววางข้อความไว้ทางขวา (แนวนอน) หรือเอา QR ไว้ด้านบนแล้ววางข้อความไว้ด้านล่าง (แนวตั้ง) แนวนอนได้ QR ใหญ่กว่าเพราะกินความสูงเต็มดวง จึงส่องติดง่ายกว่า ส่วนแนวตั้งเหมาะกับสินค้าที่ชื่อยาว เพราะข้อความได้ความกว้างเต็มดวงเลยอ่านง่ายกว่า แลกกับ QR ที่เล็กลง ถ้าเลือกแนวตั้งแล้วมีกล่องเตือนสีเหลืองขึ้นมา แปลว่าเล็กเกินไปแล้ว ให้กลับไปใช้แนวนอนหรือเลือกดวงสติกเกอร์ที่ใหญ่ขึ้น'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เลือกให้ตรงกับแผ่นสติกเกอร์ที่มีอยู่จริงในมือ ถ้าเลือกไม่ตรง ฉลากจะพิมพ์เหลื่อมออกนอกดวงทั้งแผ่นตั้งแต่ดวงแรก ขนาดที่เห็นบนจอเท่ากับขนาดจริงบนกระดาษแล้ว วัดเทียบกับแผ่นสติกเกอร์ที่มีได้เลย ถ้าไม่ได้ใช้แผ่นสติกเกอร์แต่พิมพ์ลงกระดาษธรรมดาแล้วตัดเอง เลือกขนาดไหนก็ได้ที่อ่านสบายตา'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ปกติสินค้าหนึ่งรายการใช้ฉลากหนึ่งดวง แต่ถ้าของรายการนั้นมีหลายชิ้นที่ต้องแปะแยกกัน เช่น ปากกาที่ต้องแปะทุกด้าม ให้ใส่จำนวนที่ต้องการตรงนี้ ระบบจะทำฉลากเดิมซ้ำให้ตามจำนวน จำนวนดวงทั้งหมดที่จะได้ = สินค้าที่เลือก คูณ ตัวเลขนี้ ดูยอดรวมได้ที่หัวแผ่นตัวอย่างด้านล่าง'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 5;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'นี่คือขนาดของส่วนที่เล็กที่สุดในรหัส เป็นตัวชี้ขาดว่าเครื่องอ่านจะอ่านติดหรือไม่ ตัวเลขและเกณฑ์เปลี่ยนตามชนิดรหัสที่เลือกไว้ แบบบาร์โค้ดวัดความกว้างแท่งที่แคบที่สุด ต้องได้อย่างน้อย 0.25 มม. ส่วนแบบ QR วัดความกว้างของช่องสี่เหลี่ยมเล็กที่สุด ต้องได้อย่างน้อย 0.40 มม. ซึ่งมากกว่าเพราะกล้องมือถือไม่ได้เล็งเป็นเส้นตรงเหมือนเลเซอร์ และมักถ่ายเอียงกับสั่นด้วย ถ้าต่ำกว่าเกณฑ์จะมีกล่องเตือนสีเหลืองขึ้นมา แก้ได้โดยเลือกดวงสติกเกอร์ที่ใหญ่ขึ้น ควรดูตัวเลขนี้ก่อนกดพิมพ์ทุกครั้ง เพราะถ้ารู้ตอนตัดสติกเกอร์ไปแปะของหมดแล้วจะแก้ไม่ทัน'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 6;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ฉลากที่เห็นตรงนี้คือฉลากจริงที่จะออกมาบนกระดาษ ขนาดเท่าของจริงทุกมิลลิเมตร เส้นประรอบดวงคือรอยตัด ใช้ดูว่าเนื้อหาชิดขอบเกินไปหรือเปล่า และจะถูกพิมพ์ลงกระดาษไปด้วยเพื่อให้ตัดตามได้ตรง ถ้าพิมพ์ลงแผ่นสติกเกอร์ที่ปรุรอยตัดมาแล้ว ให้เอาติ๊ก \"พิมพ์เส้นตัดประ\" ในแผงขวาออก ไม่งั้นเส้นจะไปโผล่บนดวงสติกเกอร์จริง แผ่นตัวอย่างอยู่บนจอพร้อมกับแผงตั้งค่าเสมอ ปรับอะไรก็เห็นผลตรงนี้ทันที ถ้าชื่อสินค้ายาวเกินดวง ระบบจะตัดเหลือสองบรรทัดแล้วเติมจุดไข่ปลาให้ ส่วนรหัสกับตัวบาร์โค้ดหรือ QR จะไม่ถูกย่อไม่ว่ากรณีใด ตอนนี้คู่มือเลือกสินค้าตัวอย่างให้ดูสี่รายการ พอปิดคู่มือจะกลับไปเป็นรายการที่คุณเลือกไว้เดิม'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 7;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ชี้เมาส์ที่ฉลากดวงไหนก็ได้ จะมีปุ่มดาวน์โหลดโผล่ที่มุมขวาบนของดวงนั้น กดแล้วได้ไฟล์ PNG ของฉลากดวงเดียว ใช้ตอนอยากส่งฉลากรูปเดียวให้คนอื่นทางแชท หรือเอาไปวางในเอกสารอื่น ไฟล์ที่ได้เป็นความละเอียดเต็มสำหรับพิมพ์ ไม่ใช่ขนาดที่เห็นบนจอ'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 8;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เปิดหน้าต่างพิมพ์ของเบราว์เซอร์ โดยตัดเมนู แถบเครื่องมือ และเส้นประรอยตัดออกให้หมด เหลือเฉพาะแผ่นฉลาก ก่อนกดพิมพ์จริงให้ตรวจในหน้าต่างนั้นว่าตั้งขนาดกระดาษเป็น A4 และตั้งมาตราส่วนเป็น 100% ไม่ใช่ \"ย่อให้พอดีหน้า\" เพราะการย่อจะทำให้แท่งบาร์โค้ดแคบลงกว่าที่คำนวณไว้ และฉลากจะไม่ตรงกับดวงสติกเกอร์'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 9;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'รวมฉลากทุกดวงเป็นไฟล์ PNG ไฟล์เดียว เรียงตามตารางเดียวกับที่เห็นบนจอ ใช้ตอนต้องส่งให้ร้านพิมพ์ หรือเก็บไว้พิมพ์ซ้ำทีหลังโดยไม่ต้องมาเลือกสินค้าใหม่ ถ้าเลือกไว้เยอะมากจนรวมเป็นรูปเดียวไม่ไหว ระบบจะบอกให้แบ่งเป็นหลายชุด กรณีนั้นใช้ปุ่มพิมพ์ฉลากแทนได้ เพราะการพิมพ์ไม่มีข้อจำกัดนี้'
WHERE g.`page_key` = 'product_barcode' AND s.`step_order` = 10;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'หมวด CS-MED จะออกรหัสให้สินค้าเป็น CS-MED-001, CS-MED-002 ไปเรื่อย ๆ การเปลี่ยนรหัสนำหน้าทีหลังจะมีผลกับสินค้าที่เพิ่มใหม่เท่านั้น ไม่ย้อนไปแก้ของเดิมที่ออกรหัสไปแล้ว'
WHERE g.`page_key` = 'product_category' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'หน่วยนับคือคำที่ต่อท้ายจำนวน เช่น อัน กล่อง ขวด รีม ใช้ร่วมกันทั้งระบบตั้งแต่ทะเบียนสินค้าไปจนถึงใบเบิกและรายงาน เมื่อก่อนแก้ได้ทางเดียวคือพิมพ์ชื่อใหม่ลงในช่องหน่วยของหน้าทะเบียนสินค้า ซึ่งระบบจะสร้างหน่วยใหม่ให้ทันทีถ้ายังไม่มีชื่อนั้น พิมพ์ผิดครั้งเดียวก็ได้หน่วยที่สะกดเพี้ยนติดอยู่ในรายการตลอดไป แท็บนี้มีไว้แก้ชื่อที่พิมพ์ผิด และเก็บกวาดหน่วยที่ไม่ได้ใช้แล้ว'
WHERE g.`page_key` = 'product_category' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ตัวเลขนี้บอกว่ามีสินค้ากี่รายการผูกกับหน่วยนี้อยู่ และเป็นตัวตัดสินว่าแถวนั้นลบได้หรือไม่ แถวที่ขึ้นว่า \"ยังไม่มีใครใช้\" เท่านั้นที่จะมีปุ่มกากบาทให้ลบ ส่วนแถวที่มีตัวเลขจะไม่มีปุ่มเลย เพราะถ้าลบไป สินค้าที่ใช้หน่วยนั้นจะไม่มีหน่วยเหลืออยู่ ถ้าเลิกใช้หน่วยไหนแล้วแต่ยังมีสินค้าเก่าผูกอยู่ ให้ปิดใช้งานแทน หน่วยนั้นจะหายจากรายการให้เลือกของสินค้าใหม่ แต่ของเดิมยังอ่านได้ปกติ'
WHERE g.`page_key` = 'product_category' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ค้นหาชื่อหน่วยที่สงสัยว่าซ้ำหรือสะกดผิด แล้วดับเบิลคลิกที่ช่องชื่อเพื่อแก้ได้เลย การแก้ชื่อมีผลกับสินค้าทุกรายการที่ใช้หน่วยนั้นพร้อมกัน เพราะสินค้าอ้างถึงหน่วยด้วยรหัส ไม่ได้เก็บชื่อไว้ซ้ำในตัวเอง ระบบจะไม่ยอมให้ตั้งชื่อซ้ำกับหน่วยที่มีอยู่แล้ว และจะตัดช่องว่างหัวท้ายให้เอง'
WHERE g.`page_key` = 'product_category' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ใส่จำนวนแถวที่ต้องการแล้วกดปุ่ม จะได้แถวเปล่าไว้กรอกทันที ถ้าอยู่บนแท็บหมวดหมู่ ให้ตั้งรหัสนำหน้าสั้น ๆ และสื่อความ เพราะรหัสนั้นจะติดไปกับรหัสสินค้าทุกตัวในหมวดตลอดอายุการใช้งาน ถ้าอยู่บนแท็บหน่วยนับ กรอกแค่ชื่อหน่วยอย่างเดียว ไม่มีรหัส แถวที่เพิ่มยังไม่ถูกบันทึกจนกว่าจะกดปุ่มบันทึก จะลบทิ้งด้วยปุ่มกากบาทท้ายแถวก่อนก็ได้'
WHERE g.`page_key` = 'product_category' AND s.`step_order` = 5;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'การแก้ทั้งหมดบนหน้านี้จะสะสมไว้ก่อน ยังไม่แตะฐานข้อมูลจนกว่าจะกดปุ่มนี้ ระหว่างนั้นกดยกเลิกการแก้ไขเพื่อคืนสภาพเดิมได้ตลอด เรื่องการลบให้จำไว้ว่าหมวดหมู่ที่ยังมีสินค้าผูกอยู่ลบไม่ได้ ให้ปิดใช้งานแทน ส่วนหน่วยนับลบได้เฉพาะหน่วยที่ยังไม่มีสินค้าใช้เลย ของที่ปิดใช้งานจะหายจากรายการให้เลือกของสินค้าใหม่ แต่ข้อมูลเดิมและรายงานย้อนหลังยังอ่านได้ครบเหมือนเดิม'
WHERE g.`page_key` = 'product_category' AND s.`step_order` = 6;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'สินค้าที่ไม่ได้ติ๊กให้หน่วยงานใดเลย ทุกหน่วยงานเบิกได้ตามปกติ การติ๊กที่หน้านี้คือการ \"จำกัด\" ว่ารายการนั้นให้เฉพาะหน่วยงานที่เลือกไว้เบิกเท่านั้น จึงควรติ๊กเฉพาะของที่ต้องกันไว้จริง ๆ ไม่ใช่ไล่ติ๊กให้ครบทุกหน่วยงาน (ระหว่างเปิดคู่มือนี้ ระบบใส่ข้อมูลตัวอย่างไว้ให้ดู จะหายไปเองตอนปิด)'
WHERE g.`page_key` = 'product_dept' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ตัวเลขในวงเล็บข้างชื่อคือจำนวนสินค้าที่ผูกไว้แล้ว หน่วยงานที่ไม่มีตัวเลขคือยังไม่เคยตั้งค่า ซึ่งแปลว่าเบิกได้ทุกอย่าง หลายหน่วยงานชื่อซ้ำกันข้ามบริษัท จึงมีชื่อบริษัทกำกับไว้บรรทัดล่าง และพิมพ์ค้นจากชื่อบริษัทได้ด้วย'
WHERE g.`page_key` = 'product_dept' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ฝั่งซ้ายคือสินค้าทั้งหมด แตะที่รายการเพื่อผูกเข้ากับหน่วยงานที่เลือกไว้ แตะซ้ำเพื่อเอาออก ป้าย \"ใช้ร่วมกับ\" บอกว่าตัวนั้นมีหน่วยงานอื่นใช้อยู่แล้ว ซึ่งติ๊กเพิ่มได้ ไม่ได้แย่งกัน'
WHERE g.`page_key` = 'product_dept' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ใช้คู่กับตัวกรองหมวดหมู่หรือคำค้นหา กดแล้วจะติ๊กเฉพาะรายการที่กำลังแสดงอยู่ ไม่ใช่ทั้ง 313 รายการ เหมาะกับตอนที่อยากยกทั้งหมวดให้ฝ่ายเดียว'
WHERE g.`page_key` = 'product_dept' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ดับเบิลคลิกที่ช่องไหนก็แก้ได้ทันที ไม่ต้องเปิดหน้าต่างแยก ลากคลุมหลายช่องแล้วกด Ctrl+C คัดลอกไปวางใน Excel ได้ และลากจุดมุมขวาล่างของช่องเพื่อคัดลอกค่าลงแถวถัดไปได้เหมือน Excel'
WHERE g.`page_key` = 'product_list' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ราคาที่ตั้งไว้ที่นี่จะถูกเติมให้อัตโนมัติเป็นค่าตั้งต้นตอนบันทึกรับสินค้าเข้า คนคลังยังแก้เป็นราคาที่ซื้อจริงของครั้งนั้นได้ และการแก้ตรงนั้นจะไม่ย้อนมาทับราคาที่ตั้งไว้ที่นี่'
WHERE g.`page_key` = 'product_list' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'บอกว่าใบนั้นเป็นเงินเท่าไร คิดจากราคาที่กรอกไว้ตอนรับเข้าจริง ไม่ใช่ราคาปัจจุบันของสินค้า ใบที่ขึ้นขีดกลางคือใบที่ยังไม่ได้กรอกราคา (แถวบนสุดตอนนี้เป็นตัวอย่างสำหรับสาธิต จะหายไปเองตอนปิดคู่มือ)'
WHERE g.`page_key` = 'receive_history' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ใบรับเข้าแก้ตัวเลขทีหลังไม่ได้ บันทึกผิดต้องยกเลิกทั้งใบแล้วคีย์ใหม่ การยกเลิกจะดึงยอดที่รับเข้าไปออกจากสต๊อก ถ้าของถูกเบิกออกไปแล้วจะยกเลิกไม่ได้ และต้องระบุเหตุผลทุกครั้ง'
WHERE g.`page_key` = 'receive_history' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ปุ่มซ้ายให้ไฟล์แถวละหนึ่งใบ ส่วนปุ่มนี้แตกเป็นรายบรรทัดพร้อมราคาต่อหน่วย ใช้ตอบคำถามแบบ \"เดือนนี้รับผ้าพันแผลกี่ครั้ง ครั้งละราคาเท่าไร\" ซึ่งไฟล์แบบแรกกลืนสองราคารวมกันจนแยกไม่ออก'
WHERE g.`page_key` = 'receive_history' AND s.`step_order` = 5;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ค้นจากเลขที่เอกสารหรือหมายเหตุได้ ด้านล่างยังกรองตามช่วงวันที่และสถานะได้อีก ทั้งตารางและไฟล์ที่ส่งออกใช้เงื่อนไขชุดเดียวกัน สิ่งที่เห็นบนจอกับในไฟล์จึงตรงกันเสมอ (บนจอแคบ ตัวกรองจะพับอยู่หลังปุ่มบนแถบเครื่องมือ)'
WHERE g.`page_key` = 'receive_history' AND s.`step_order` = 6;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ใบรับเข้าไม่มีขั้นตอนอนุมัติ กดบันทึกปุ๊บยอดคงเหลือขึ้นเลย ถ้าบันทึกผิดต้องไปยกเลิกทั้งใบที่หน้าประวัติการรับเข้า ไม่ใช่กลับมาแก้ตัวเลข (ระหว่างเปิดคู่มือนี้ ระบบใส่รายการตัวอย่างไว้ให้ดู จะหายไปเองตอนปิด)'
WHERE g.`page_key` = 'receive_new' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ถ้าของที่รับเข้ามามีฉลากแปะอยู่ ให้คลิกที่ช่องนี้แล้วยิงได้เลย ระบบจะเพิ่มบรรทัดพร้อมสินค้าและราคาให้ทันที ยิงซ้ำสินค้าตัวเดิมจะบวกจำนวนขึ้นทีละหนึ่ง ไม่ได้สร้างบรรทัดซ้ำ จึงเดินยิงของทีละชิ้นได้เลยโดยไม่ต้องนับก่อน ยิงถูกจะได้ยินเสียงสูงสั้น ยิงไม่เจอจะได้เสียงต่ำยาว ฟังได้โดยไม่ต้องละสายตาจากของ ช่องนี้รับได้ทั้งฉลากแบบบาร์โค้ดและแบบ QR โดยไม่ต้องสลับโหมด เพราะทั้งสองแบบเก็บรหัสสินค้าตัวเดียวกัน แต่ต้องดูที่ตัวเครื่องด้วย เครื่องยิงเลเซอร์แบบเส้นตรงอ่านได้แต่บาร์โค้ด ถ้าจะยิง QR ต้องเป็นรุ่นที่เป็นกล้อง ฉลากทั้งสองแบบพิมพ์ได้จากเมนู ข้อมูลสินค้า > บาร์โค้ดสินค้า'
WHERE g.`page_key` = 'receive_new' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'กดปุ่มนี้เพื่อเปิดกล้องของเครื่องแล้วส่อง QR ที่ฉลากแทนการยิง เหมาะกับตอนเปิดหน้านี้จากมือถือขณะยืนอยู่ที่กองของ ไม่ต้องกดถ่าย เล็งให้ QR อยู่ในกรอบแล้วระบบอ่านเอง ส่องติดแล้วจะเพิ่มบรรทัดให้เหมือนการยิงทุกอย่าง แล้วปิดกล้องให้เองหลังจากโชว์ผลให้อ่านครู่หนึ่ง ถ้าส่องผิดตัวหรือไม่พบรหัส กล้องจะเปิดค้างไว้ให้เล็งตัวใหม่ต่อได้เลย ข้อจำกัดสองข้อที่ต้องรู้: กล้องอ่านได้เฉพาะ QR ไม่ใช่บาร์โค้ด และเบราว์เซอร์จะไม่ยอมเปิดกล้องถ้าระบบยังเข้าผ่าน http ธรรมดา ถ้ากดแล้วขึ้นข้อความสีแดงเรื่องนี้ ให้แจ้งผู้ดูแลระบบ ไม่ใช่ความผิดพลาดของโปรแกรม'
WHERE g.`page_key` = 'receive_new' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เลือกสินค้าแล้วช่องราคาจะเติมราคาจากทะเบียนสินค้าให้เอง ถ้ารอบนี้ซื้อได้ราคาอื่นก็แก้ทับได้เลย ราคาที่กรอกตรงนี้คือราคาที่ระบบเอาไปคิดต้นทุนถัวเฉลี่ย จึงควรกรอกให้ครบทุกบรรทัด ไม่งั้นรายงานค่าใช้จ่ายจะขึ้นศูนย์'
WHERE g.`page_key` = 'receive_new' AND s.`step_order` = 5;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ตัวเลขทั้งหน้าเปลี่ยนตามเดือนที่เลือก ทุกยอดคิดจากราคาที่กรอกไว้ตอนรับเข้าจริง ใบที่ไม่ได้กรอกราคาจะถูกนับเป็นศูนย์ ทำให้ยอดต่ำกว่าความจริงโดยไม่มีอะไรฟ้อง จึงควรไล่กรอกราคาให้ครบก่อนใช้หน้านี้สรุปส่งบัญชี'
WHERE g.`page_key` = 'report_cost' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'จ่ายออก คือมูลค่าของที่เบิกออกไปใช้ในเดือนนี้ — เป็นค่าใช้จ่ายจริงของหน่วยงาน · รับเข้า คือเงินที่จ่ายซื้อของเข้าคลังในเดือนนี้ — เป็นเงินที่ออกจากบริษัท · มูลค่าคงคลัง คือของที่ยังเหลืออยู่ ณ สิ้นเดือน สองตัวแรกไม่จำเป็นต้องเท่ากัน เพราะของที่ซื้อเดือนนี้อาจถูกเบิกเดือนหน้า'
WHERE g.`page_key` = 'report_cost' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ยอดค่าใช้จ่ายของแต่ละบริษัท คิดจากบริษัทที่หน่วยงานผู้เบิกสังกัดอยู่ กดที่แถวไหนก็ได้เพื่อเปิดแผงรายละเอียดว่ายอดนั้นมาจากเอกสารใบไหนบ้าง เป็นคำถามที่บัญชีถามเสมอเวลาตัวเลขไม่ตรงกับที่คาดไว้'
WHERE g.`page_key` = 'report_cost' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'คนละเรื่องกับสามตารางบน — ตารางนี้คือเงินที่จ่ายซื้อของเข้าคลัง ไม่ใช่ของที่ถูกเบิกไปใช้ ราคาต่อหน่วยที่เห็นคือราคาที่คีย์ไว้ตอนรับเข้าจริง ของตัวเดียวกันที่รับหลายครั้งคนละราคาจะแยกบรรทัดให้เห็น'
WHERE g.`page_key` = 'report_cost' AND s.`step_order` = 6;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'รออนุมัติ คือรอผู้อนุมัติตัดสิน · อนุมัติแล้ว คือรอคลังจ่ายของ · จ่ายแล้ว คือคลังจ่ายครบทุกบรรทัดแล้ว ไอคอนท้ายแถวเปลี่ยนตามสถานะ ใบที่ไม่มีอะไรให้ทำจะเหลือแค่ดูกับพิมพ์ (แถวบนสุดตอนนี้เป็นตัวอย่างสำหรับสาธิต จะหายไปเองตอนปิดคู่มือ)'
WHERE g.`page_key` = 'request_list' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เปิดดูรายการสินค้าทั้งใบก่อนตัดสินใจ ควรกดทุกครั้งก่อนอนุมัติ เพราะการอนุมัติคือการยืนยันว่าของทั้งใบสมเหตุสมผล ไม่ใช่แค่ยืนยันว่ามีใบเข้ามา จุดสีข้างไอคอนนี้แปลว่าใบนั้นมีงานรออยู่ที่คุณ'
WHERE g.`page_key` = 'request_list' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'อนุมัติแล้วใบจะไปรอที่คลังเพื่อทำใบจ่าย ยังไม่ตัดสต๊อกตอนนี้ ระบบจะแจ้งผู้ขอเบิกให้เองทั้งกระดิ่งและอีเมล ผู้อนุมัติอนุมัติใบของตัวเองไม่ได้ ไอคอนนี้จะไม่ขึ้นในใบของคุณเอง'
WHERE g.`page_key` = 'request_list' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ส่งใบเบิกแล้วของยังไม่ถูกตัดออกจากคลัง ต้องรอผู้อนุมัติตัดสิน แล้วคลังทำใบจ่ายอีกที ยอดคงเหลือที่เห็นจึงเป็นยอดจริงตอนนี้ ไม่ได้หักใบเบิกที่คนอื่นส่งไปแล้ว (ระหว่างเปิดคู่มือนี้ ระบบใส่รายการตัวอย่างไว้ให้ดู จะหายไปเองตอนปิด)'
WHERE g.`page_key` = 'request_new' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ระบบเลือกหน่วยงานต้นสังกัดให้ล่วงหน้าแล้ว ผู้ดูแลระบบเปลี่ยนเป็นหน่วยงานอื่นได้เพื่อทำแทน แต่ระวัง — เปลี่ยนหน่วยงานแล้วรายการที่เลือกไว้จะถูกล้าง เพราะสินค้าที่แต่ละหน่วยงานเบิกได้ไม่เหมือนกัน'
WHERE g.`page_key` = 'request_new' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ถ้ากำลังยืนอยู่หน้าชั้นวางและเห็นของจริง ยิงฉลากที่ติดอยู่ได้เลย เร็วกว่าไล่หาชื่อในรายการ ยิงแล้วสินค้าจะไปอยู่ฝั่งขวาทันที ยิงซ้ำตัวเดิมจะบวกจำนวนขึ้นทีละหนึ่ง ช่องนี้รับได้ทั้งฉลากแบบบาร์โค้ดและแบบ QR โดยไม่ต้องสลับโหมด ถ้ายิงแล้วขึ้นว่าไม่พบ ให้ดูก่อนว่าเลือกหน่วยงานถูกหรือยัง เพราะแต่ละหน่วยงานเบิกสินค้าได้ไม่เหมือนกัน สินค้าที่หน่วยงานนี้ไม่มีสิทธิ์เบิกจะยิงไม่ติด แต่ถ้ายิง QR แล้วไม่มีอะไรขึ้นในช่องเลยแม้แต่ตัวอักษรเดียว แปลว่าเครื่องยิงที่ใช้อยู่เป็นรุ่นเลเซอร์เส้นตรงซึ่งอ่าน QR ไม่ได้ ให้ใช้ฉลากแบบบาร์โค้ดแทน'
WHERE g.`page_key` = 'request_new' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'กดปุ่มนี้เพื่อเปิดกล้องของเครื่องแล้วส่อง QR ที่ฉลากแทนการยิง เหมาะกับตอนยืนอยู่หน้าชั้นวางแล้วเปิดหน้านี้จากมือถือ ไม่ต้องกดถ่าย เล็งให้ QR อยู่ในกรอบแล้วระบบอ่านเอง ส่องติดแล้วสินค้าจะไปอยู่ฝั่งขวาเหมือนการยิงทุกอย่าง แล้วปิดกล้องให้เองหลังจากโชว์ผลให้อ่านครู่หนึ่ง ถ้าส่องแล้วไม่พบ กล้องจะเปิดค้างไว้ให้เล็งตัวใหม่ต่อ อย่าลืมว่าต้องเลือกหน่วยงานก่อน เพราะสินค้าที่หน่วยงานนั้นไม่มีสิทธิ์เบิกจะส่องไม่ติด ข้อจำกัดสองข้อ: กล้องอ่านได้เฉพาะ QR ไม่ใช่บาร์โค้ด และเบราว์เซอร์จะไม่ยอมเปิดกล้องถ้าระบบยังเข้าผ่าน http ธรรมดา'
WHERE g.`page_key` = 'request_new' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ของที่เพิ่งเลือกจะขึ้นบนสุดเสมอ กรอกจำนวนที่ต้องการจริงในช่อง และใส่หมายเหตุรายบรรทัดได้ถ้าต้องอธิบายเหตุผล ซึ่งช่วยให้ผู้อนุมัติตัดสินใจได้เร็วขึ้น'
WHERE g.`page_key` = 'request_new' AND s.`step_order` = 7;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'เมลทุกฉบับเข้าคิวก่อนเสมอ แล้วตัวส่งเบื้องหลังหยิบไปส่งภายในสิบวินาที ฉบับที่ส่งไม่ผ่านสามครั้งจะกลายเป็นล้มเหลวและหยุดลองใหม่ ต้องกด \"เอากลับเข้าคิว\" เอง ปุ่ม \"ส่งคิวเดี๋ยวนี้\" ใช้ตอนอยากส่งทันทีโดยไม่รอรอบ'
WHERE g.`page_key` = 'settings' AND s.`step_order` = 4;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ทุกบรรทัดที่เห็นคือหนึ่งขั้นตอนของคู่มือหน้าใดหน้าหนึ่ง แก้หัวข้อและคำอธิบายได้ในช่องโดยตรง ผู้ใช้จะเห็นข้อความใหม่ทันทีที่เปิดคู่มือครั้งถัดไป มีไว้ให้ปรับถ้อยคำตามวิธีทำงานจริงของที่นี่ เช่นเปลี่ยนคำเรียกเอกสารให้ตรงกับที่คนที่นี่เรียกกัน โดยไม่ต้องแก้โปรแกรม'
WHERE g.`page_key` = 'settings_guide' AND s.`step_order` = 1;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ขั้นตอนทั้งหมดรวมกันเกือบร้อยบรรทัดจากทุกหน้าในระบบ ไล่หาทีละบรรทัดจะเสียเวลา พิมพ์คำที่จำได้จากข้อความที่เห็นบนหน้าจอลงช่องนี้ จะกรองเหลือเฉพาะขั้นที่มีคำนั้น ค้นจากชื่อหน้าก็ได้ถ้าอยากดูทั้งหน้าพร้อมกัน'
WHERE g.`page_key` = 'settings_guide' AND s.`step_order` = 2;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'แก้กี่บรรทัดก็ได้ ระบบจะสะสมไว้ก่อนแล้วส่งทีเดียวตอนกดปุ่มนี้ ตัวเลขบนปุ่มบอกว่ามีกี่ช่องที่ยังไม่ได้บันทึก ถ้าปิดหน้าไปก่อนกดบันทึก สิ่งที่พิมพ์ไว้จะหายทั้งหมด ระบบจะเตือนก่อนออกจากหน้าให้'
WHERE g.`page_key` = 'settings_guide' AND s.`step_order` = 3;

UPDATE `tb_guide_step` s INNER JOIN `tb_guide` g ON g.`guide_id` = s.`guide_id`
SET s.`description` = 'ปกติคู่มือของแต่ละหน้าจะเด้งขึ้นเองครั้งเดียว แล้วระบบจำไว้ว่าคนนี้ดูไปแล้ว ปุ่มนี้ล้างความจำนั้นทิ้งทั้งระบบ ทำให้คู่มือกลับมาเด้งใหม่ทุกหน้าสำหรับทุกคน ใช้ตอนแก้ข้อความไปแล้วอยากให้ทุกคนได้เห็นของใหม่ หรือตอนมีพนักงานเข้าใหม่หลายคนพร้อมกัน'
WHERE g.`page_key` = 'settings_guide' AND s.`step_order` = 4;

